  "passages": [
    {
      "id": "a22-14-r1",
      "lesson": 14,
      "title": "یک بسته برای نورا",
      "text": "Am Freitag hat Nora Geburtstag. Ihr Bruder Sami kauft ihr eine Tasse und ein Buch. Die Tasse wird zuerst in weiches Papier eingepackt. Danach werden beide Geschenke in einen Karton gelegt. Sami schreibt die Adresse auf ein Etikett. Am Samstag bringt er das Paket zur Post. Nora wohnt in Hamburg."
    },
    {
      "id": "a22-14-r2",
      "lesson": 14,
      "title": "نامهٔ تشکر",
      "text": "Liebe Leila, gestern ist dein Päckchen angekommen. Vielen Dank für die Handschuhe! Sie passen mir sehr gut. Heute habe ich sie auf dem Weg zur Arbeit getragen. Auch die Karte hat mich sehr gefreut. Am Sonntag möchte ich dich anrufen. Vielleicht können wir nächste Woche zusammen Kaffee trinken. Liebe Grüße, Ben"
    },
    {
      "id": "a22-15-r1",
      "lesson": 15,
      "title": "برنامهٔ امشب",
      "text": "Heute Abend sehen Mina und Paul zusammen fern. Um 19 Uhr gibt es eine Dokumentation über Tiere. Um 20:15 Uhr beginnt eine Komödie. Paul möchte lieber einen Krimi sehen, aber der fängt erst um 22 Uhr an. Mina muss morgen früh arbeiten. Deshalb wählen sie die Komödie. Paul bringt ihr ein Glas Wasser und gibt ihr die Fernbedienung."
    },
    {
      "id": "a22-15-r2",
      "lesson": 15,
      "title": "عادت‌های رسانه‌ای",
      "text": "Roya benutzt ihr Handy jeden Morgen zehn Minuten für Nachrichten. Im Bus hört sie Musik. Einen Fernseher hat sie nicht. Am Freitag sieht sie mit ihrer Schwester eine Serie am Laptop. Die Schwester empfiehlt ihr oft neue Serien. Roya liest abends lieber ein Buch. Am Sonntag bleiben Handy und Laptop meistens ausgeschaltet."
    },
    {
      "id": "a22-16-r1",
      "lesson": 16,
      "title": "تأیید رزرو",
      "text": "Sehr geehrte Frau Rahimi, wir bestätigen Ihre Reservierung vom 12. bis zum 15. Mai: ein Doppelzimmer für drei Nächte. Das Zimmer kostet 110 Euro pro Nacht, inklusive Frühstück. Sie können ab 15 Uhr einchecken. Am Abreisetag bitten wir Sie, das Zimmer bis 11 Uhr zu verlassen. Der Parkplatz kostet zusätzlich 8 Euro pro Tag. Mit freundlichen Grüßen, Ihr Hotelteam"
    },
    {
      "id": "a22-16-r2",
      "lesson": 16,
      "title": "مسیر در هتل",
      "text": "Gast: Entschuldigung, können Sie mir sagen, wo der Fitnessraum ist? Mitarbeiterin: Ja. Gehen Sie durch die Eingangshalle. Dann gehen Sie am Restaurant vorbei und nehmen den Aufzug in den zweiten Stock. Der Fitnessraum liegt gegenüber vom Konferenzraum. Gast: Danke. Wissen Sie auch, wann er schließt? Mitarbeiterin: Heute um 21 Uhr. Die Sauna schließt schon um 20 Uhr."
    }
  ],
